    #[test]
    fn should_parse_review_thread_reply_resolve_reopen_dismiss_commands() {
        let reply = parse_for_test(&[
            "tuicr",
            "review",
            "thread",
            "reply",
            "--session",
            "s.json",
            "--thread",
            "abc",
