use std::fs::File;
use std::io::{self, Write};
use std::sync::mpsc;
use std::time::{Duration, Instant};

use crossterm::{
    event::{self, Event, KeyEventKind},
    execute, queue,
    terminal::{BeginSynchronizedUpdate, EndSynchronizedUpdate, supports_keyboard_enhancement},
};

use tuicr::app::{self, App, AppStartupOptions, FocusedPanel, InputMode};
use tuicr::cli::parse_cli_args;
use tuicr::editor::{EditorError, EditorTarget};
use tuicr::handler::{
    handle_command_action, handle_comment_action, handle_comment_navigator_action,
    handle_commit_select_action, handle_commit_selector_action, handle_confirm_action,
    handle_diff_action, handle_file_list_action, handle_help_action, handle_mouse_event,
    handle_search_action, handle_submit_action_picker_action, handle_submit_confirm_action,
    handle_submit_resolver_action, handle_visual_action,
};
use tuicr::input::{Action, map_key_to_action, map_target_filter_mode};
use tuicr::terminal_state::{TerminalFeatures, TerminalSession};
use tuicr::theme::resolve_theme_with_config;
use tuicr::vcs::{DiffWhitespaceMode, GitBackendPreference};
use tuicr::{config, handler, profile, ui, update};

/// Timeout for the "press Ctrl+C again to exit" feature
const CTRL_C_EXIT_TIMEOUT: Duration = Duration::from_secs(2);
/// Hide the file list by default on narrow terminals.
const MIN_WIDTH_FOR_FILE_LIST: u16 = 100;

fn main() -> anyhow::Result<()> {
    profile::init_from_env();

    // Setup panic hook to restore terminal on panic
    let original_hook = std::panic::take_hook();
    std::panic::set_hook(Box::new(move |panic_info| {
        tuicr::terminal_state::restore_stdio_best_effort();
        original_hook(panic_info);
    }));

    // Parse CLI arguments and resolve theme
    // This also configures syntax highlighting colors before diff parsing
    let mut cli_args = profile::time("startup.parse_cli_args", parse_cli_args);
    if cli_args.update_command {
        // Keep self-update disabled until this fork owns a stable release
        // channel; never fall through to the inherited upstream channel.
        eprintln!(
            "tuicr-fork: `tuicr update` is disabled in this fork build.\n\
             This binary will never contact crates.io, GitHub Releases, Homebrew, cargo, or mise.\n\
             Reinstall from a verified fork release archive, Cargo git tag, or Nix flake.\n\
             See RELEASE.md and README.md for details."
        );
        std::process::exit(1);
    }
    if let Some(review_command) = cli_args.review_command.take() {
        tuicr::review_cli::run(review_command)?;
        return Ok(());
    }

    // Check keyboard enhancement support before enabling raw mode.
    // Skip when --stdout is used because the probe writes escape sequences to stdout,
    // which would leak into the captured export output.
    let keyboard_enhancement_supported = if cli_args.output_to_stdout {
        false
    } else {
        matches!(supports_keyboard_enhancement(), Ok(true))
    };

    // --path implies --working-tree unless -r is explicitly provided
    if cli_args.path_filter.is_some() && !cli_args.working_tree && cli_args.revisions.is_none() {
        cli_args.working_tree = true;
    }
    let mut startup_warnings = Vec::new();
    let config_outcome = profile::time("startup.load_config", || match config::load_config() {
        Ok(outcome) => outcome,
        Err(e) => {
            startup_warnings.push(format!("Failed to load config: {e}"));
            config::ConfigLoadOutcome::default()
        }
    });
    startup_warnings.extend(config_outcome.warnings);
    let (mut theme, theme_warnings) = profile::time("startup.resolve_theme", || {
        resolve_theme_with_config(
            cli_args.theme,
            cli_args.appearance,
            config_outcome
                .config
                .as_ref()
                .and_then(|cfg| cfg.theme.as_deref()),
            config_outcome
                .config
                .as_ref()
                .and_then(|cfg| cfg.theme_dark.as_deref()),
            config_outcome
                .config
                .as_ref()
                .and_then(|cfg| cfg.theme_light.as_deref()),
            config_outcome
                .config
                .as_ref()
                .and_then(|cfg| cfg.appearance.as_deref()),
        )
    })
    .unwrap_or_else(|err| {
        eprintln!("Error: {err}");
        std::process::exit(2);
    });
    startup_warnings.extend(theme_warnings);

    let transparent = config_outcome
        .config
        .as_ref()
        .and_then(|cfg| cfg.transparent_background)
        .unwrap_or(true);
    if transparent {
        theme.panel_bg = ratatui::style::Color::Reset;
    }

    let no_update_check = cli_args.no_update_check
        || config_outcome
            .config
            .as_ref()
            .and_then(|cfg| cfg.no_update_check)
            .unwrap_or(false);

    // Start update check in background (non-blocking)
    let update_rx = if !no_update_check {
        let (tx, rx) = mpsc::channel();
        std::thread::spawn(move || {
            let result = update::check_for_updates();
            let _ = tx.send(result); // Ignore send error if receiver dropped
        });
        Some(rx)
    } else {
        None
    };

    // Initialize app
    let git_backend_preference = GitBackendPreference::from_config(
        config_outcome
            .config
            .as_ref()
            .and_then(|cfg| cfg.backend.as_deref()),
    );
    let diff_whitespace_mode = if config_outcome
        .config
        .as_ref()
        .and_then(|cfg| cfg.ignore_whitespace)
        .unwrap_or(false)
    {
        DiffWhitespaceMode::IgnoreAll
    } else {
        DiffWhitespaceMode::Normal
    };

    let commit_order = match config_outcome
        .config
        .as_ref()
        .and_then(|cfg| cfg.commit_order.as_deref())
    {
        Some("ascending") => app::CommitOrder::Ascending,
        _ => app::CommitOrder::Descending,
    };
    let commit_selection = match config_outcome
        .config
        .as_ref()
        .and_then(|cfg| cfg.initial_commit_selection.as_deref())
    {
        Some("oldest") => app::CommitSelectionStart::Oldest,
        _ => app::CommitSelectionStart::All,
    };

    let mut app = match profile::time("startup.app_init", || {
        App::new(
            theme,
            config_outcome
                .config
                .as_ref()
                .and_then(|cfg| cfg.comment_types.clone()),
            cli_args.output_to_stdout,
            AppStartupOptions {
                revisions: cli_args.revisions.as_deref(),
                working_tree: cli_args.working_tree,
                path_filter: cli_args.path_filter.as_deref(),
                file_path: cli_args.file_path.as_deref(),
                all_files: cli_args.all_files,
                git_backend_preference,
                diff_whitespace_mode,
                commit_selection,
                pr_target: cli_args.pr_target.as_deref(),
                repo_url_override: cli_args
                    .repo_url
                    .as_deref()
                    .and_then(tuicr::forge::parse_any_remote_url),
            },
        )
    }) {
        Ok(mut app) => {
            app.supports_keyboard_enhancement = keyboard_enhancement_supported;
            startup_warnings.extend(app.vcs.startup_warnings());
            if let Some(cfg) = config_outcome.config.as_ref() {
                if let Some(forge_cfg) = cfg.forge.clone() {
                    app.forge_config = forge_cfg;
                }
                if let Some(leader) = cfg.leader {
                    app.leader_key = leader;
                }
                app.comment_vim_enabled = cfg.comment_vim.unwrap_or(false);
                if let Some(w) = cfg.comment_tab_width {
                    app.comment_tab_width = w;
                }
                if let Some(username) = cfg
                    .username
                    .as_deref()
                    .map(str::trim)
                    .filter(|s| !s.is_empty())
                {
                    app.username = username.to_string();
                }
            }
            app
        }
        Err(e) => {
            eprintln!("Error: {e}");
            // The "you need to be in a git repo" hint is only meaningful
            // when the failure was the absence of a repo. For other
            // startup errors — `tuicr pr <bad-url>`, forge auth issues,
            // missing PR, `--file <missing-path>` — the hint is wrong.
            if matches!(e, tuicr::error::TuicrError::NotARepository) {
                if cli_args.all_files {
                    eprintln!(
                        "\ntuicr --all-files requires a git repository with tracked files. Run `git init && git add -A` to bootstrap one."
                    );
                } else {
                    eprintln!(
                        "\nMake sure you're in a git, jujutsu, or mercurial repository with commits or staged/unstaged changes."
                    );
                }
            }
            std::process::exit(1);
        }
    };

    // Commit selector presentation/behavior prefs. `initial_commit_selection`
    // also fed `App::new` for the initial `-r`/PR range; keep it on the app so
    // re-selections during the session (target selector, PR reload) honor it.
    app.commit_order = commit_order;
    app.commit_selection_start = commit_selection;

    if let Err(e) = app.ensure_ephemeral_session_file() {
        startup_warnings.push(format!("Failed to initialize review session file: {e}"));
    }

    // Announce the slug for the active session so agents and wrapper scripts
    // can discover it without parsing the markdown export. This is emitted to
    // stderr before the alt-screen swap so the line stays on the user's
    // scrollback after tuicr exits.
    if let Some(slug) = app.session_slug() {
        eprintln!("tuicr-session: {slug}");
    }

    // When --stdout is used, render TUI to /dev/tty so stdout is free for export output
    let tty_output: Box<dyn Write> = if cli_args.output_to_stdout {
        Box::new(File::options().write(true).open("/dev/tty")?)
    } else {
        Box::new(io::stdout())
    };
    let mouse_enabled = config_outcome
        .config
        .as_ref()
        .and_then(|cfg| cfg.mouse)
        .unwrap_or(true);
    let mut terminal = TerminalFeatures::new()
        .mouse_enabled(mouse_enabled)
        .keyboard_enhancements_supported(keyboard_enhancement_supported)
        .enter(tty_output)?;

    // Apply config-driven defaults
    if let Some(ref cfg) = config_outcome.config {
        if cfg.show_file_list == Some(false) {
            app.show_file_list = false;
            app.focused_panel = FocusedPanel::Diff;
        }
        // Start with the commit selector pane hidden. `(` / `)` still cycle the
        // selected commit while hidden; `<leader>s` / `:set commits!` reveal it.
        if cfg.show_commits == Some(false) {
            app.show_commit_selector = false;
            if app.focused_panel == FocusedPanel::CommitSelector {
                app.focused_panel = FocusedPanel::Diff;
            }
        }
        // Pristine mode has no diff, so side-by-side would render two
        // identical panes. Honor the config for every other mode.
        if cfg.diff_view.as_deref() == Some("side-by-side") && !app.is_pristine_mode {
            app.diff_view_mode = app::DiffViewMode::SideBySide;
        }
        if let Some(wrap) = cfg.wrap {
            app.diff_state.wrap_lines = wrap;
        }
        // Open in single-file view when the user opts in. Pristine
        // `--all-files` already turned it on inside `App::new`, so we
        // only toggle if it's still off.
        if cfg.single_file_view == Some(true) && !app.is_single_file_view {
            app.toggle_single_file_view();
        }
        app.export = cfg.resolved_export();
        if cfg.cursor_line == Some(false) {
            app.cursor_line_highlight = false;
        }
        if let Some(scroll_offset) = cfg.scroll_offset {
            app.scroll_offset = scroll_offset;
        }
        if let Some(interval_ms) = cfg.review_watch_interval_ms {
            app.set_review_watch_interval_ms(interval_ms as u64);
        }
    }

    // On narrow terminals, start with only the diff panel visible.
    if let Ok((width, _)) = crossterm::terminal::size()
        && width < MIN_WIDTH_FOR_FILE_LIST
    {
        app.show_file_list = false;
        app.focused_panel = FocusedPanel::Diff;
    }

    if let Some(message) = startup_warnings.first() {
        app.set_warning(message.clone());
    }

    // Track pending z command for zz centering
    let mut pending_z = false;
    // Track pending Z command for ZZ export+quit / ZQ quit
    let mut pending_shift_z = false;
    // Track pending d command for dd delete
    let mut pending_d = false;
    // Track pending leader command for leader-prefixed actions.
    let mut pending_leader = false;
    // Track pending Ctrl+C for "press twice to exit" (with timestamp for 2s timeout)
    let mut pending_ctrl_c: Option<Instant> = None;
    // Only re-render when state actually changed; the diff renderer rebuilds
    // every line on each draw, so idle redraws are expensive on large diffs.
    let mut needs_redraw = true;

    // Main loop
    loop {
        // Check for update result (non-blocking)
        if let Some(ref rx) = update_rx
            && let Ok(
                update::UpdateCheckResult::UpdateAvailable(info)
                | update::UpdateCheckResult::AheadOfRelease(info),
            ) = rx.try_recv()
        {
            app.update_info = Some(info);
            needs_redraw = true;
        }

        // Auto-clear expired pending Ctrl+C state and message
        if let Some(first_press) = pending_ctrl_c
            && first_press.elapsed() >= CTRL_C_EXIT_TIMEOUT
        {
            pending_ctrl_c = None;
            app.message = None;
            needs_redraw = true;
        }

        needs_redraw |= app.clear_expired_message();

        // Snapshot before polling so the tick that drains a channel (clearing
        // its rx) still triggers a redraw with the applied result. While work
        // is pending we redraw every tick anyway so spinners animate.
        let pr_pending = app.has_pending_pr_work();
        app.poll_pr_load_events();
        app.poll_pr_open_events();
        app.poll_pr_reload_events();
        app.poll_pr_range_reload_events();
        app.poll_pr_threads_events();
        app.poll_pr_submit_events();
        needs_redraw |= app.poll_persisted_session_changes();
        needs_redraw |= pr_pending;

        if needs_redraw {
            // Bracket the frame in a synchronized-output pair (CSI ?2026h/l)
            // so terminals (and zellij) buffer the whole repaint and present
            // it atomically. Without this, scrolling over a slow link visibly
            // tears as escape sequences arrive in chunks. Terminals that do
            // not support DEC 2026 ignore it.
            queue!(terminal.backend_mut(), BeginSynchronizedUpdate)?;
            terminal.draw(|frame| {
                ui::render(frame, &mut app);
            })?;
            execute!(terminal.backend_mut(), EndSynchronizedUpdate)?;
            needs_redraw = false;
        }

        // Handle events
        if event::poll(Duration::from_millis(100))? {
            // Set before reading so the many `continue` paths below (leader
            // keys, zz/ZZ, dd, {count}G, …) still schedule a redraw on the
            // next iteration even though they short-circuit past the match.
            needs_redraw = true;
            let event = event::read()?;
            // Down/Up Release flips the `*_released_since_arm` flag so the
            // primed two-press file walk in single-file view requires a
            // deliberate release + press; held-key auto-repeat (Repeat
            // events) never satisfies the gate. Terminals without kitty
            // REPORT_EVENT_TYPES support never emit Release, in which case
            // `supports_keyboard_enhancement` is false and `cursor_down` /
            // `cursor_up` skip the gate entirely.
            if let Event::Key(key) = &event
                && key.kind == KeyEventKind::Release
            {
                if matches!(
                    key.code,
                    crossterm::event::KeyCode::Down | crossterm::event::KeyCode::Char('j')
                ) {
                    app.down_released_since_arm = true;
                }
                if matches!(
                    key.code,
                    crossterm::event::KeyCode::Up | crossterm::event::KeyCode::Char('k')
                ) {
                    app.up_released_since_arm = true;
                }
            }
            match event {
                Event::Key(key)
                    if matches!(key.kind, KeyEventKind::Press | KeyEventKind::Repeat) =>
                {
                    // Handle Ctrl+C twice to exit (works across all input modes)
                    // In Comment mode, first Ctrl+C also cancels the comment
                    if key.code == crossterm::event::KeyCode::Char('c')
                        && key
                            .modifiers
                            .contains(crossterm::event::KeyModifiers::CONTROL)
                    {
                        // If in comment mode, cancel the comment first
                        if app.input_mode == InputMode::Comment {
                            app.exit_comment_mode();
                        }

                        if let Some(first_press) = pending_ctrl_c
                            && first_press.elapsed() < CTRL_C_EXIT_TIMEOUT
                        {
                            // Second Ctrl+C within timeout - exit immediately
                            app.should_quit = true;
                            continue;
                        }
                        // First Ctrl+C (or timeout expired) - show warning and start timer
                        pending_ctrl_c = Some(Instant::now());
                        app.set_message("Press Ctrl+C again to exit");
                        continue;
                    }

                    // Any other key clears the pending Ctrl+C state and message
                    if pending_ctrl_c.is_some() {
                        pending_ctrl_c = None;
                        app.message = None;
                    }

                    // Handle pending z command for zz/zt/zb viewport positioning
                    if pending_z {
                        pending_z = false;
                        match key.code {
                            crossterm::event::KeyCode::Char('z') => {
                                app.center_cursor();
                                continue;
                            }
                            crossterm::event::KeyCode::Char('t') => {
                                app.cursor_to_top();
                                continue;
                            }
                            crossterm::event::KeyCode::Char('b') => {
                                app.cursor_to_bottom();
                                continue;
                            }
                            _ => {} // Fall through to normal handling
                        }
                    }

                    // Handle pending Z command for ZZ (export+quit) / ZQ (quit)
                    if pending_shift_z {
                        pending_shift_z = false;
                        match key.code {
                            crossterm::event::KeyCode::Char('Z') => {
                                // ZZ: save session, export, and quit (same as :wq)
                                let _ = app.save_current_session_merging_external();
                                if app.session.has_comments() {
                                    handler::handle_export_and_quit(&mut app);
                                } else {
                                    app.should_quit = true;
                                }
                                continue;
                            }
                            crossterm::event::KeyCode::Char('Q') => {
                                // ZQ: quit without exporting (same as q)
                                app.should_quit = true;
                                continue;
                            }
                            _ => {} // Fall through to normal handling
                        }
                    }

                    // Handle pending d command for dd delete comment
                    if pending_d {
                        pending_d = false;
                        if key.code == crossterm::event::KeyCode::Char('d') {
                            if app.cursor_on_locked_comment() {
                                app.set_message(
                                    "Comment already pushed to GitHub — read only in tuicr",
                                );
                            } else if !app.delete_comment_at_cursor() {
                                if app.cursor_on_remote_thread() {
                                    app.set_message("GitHub comment — read only in tuicr");
                                } else {
                                    app.set_message("No comment at cursor");
                                }
                            }
                            continue;
                        }
                        // Otherwise fall through to normal handling
                    }

                    // Handle pending leader command for panel focus, file list toggle, and review comments.
                    if pending_leader {
                        pending_leader = false;
                        match key.code {
                            crossterm::event::KeyCode::Char('e') => {
                                app.toggle_file_list();
                                continue;
                            }
                            crossterm::event::KeyCode::Char('h') => {
                                if app.show_file_list {
                                    app.focused_panel = app::FocusedPanel::FileList;
                                }
                                continue;
                            }
                            crossterm::event::KeyCode::Char('l') => {
                                app.focused_panel = app::FocusedPanel::Diff;
                                continue;
                            }
                            crossterm::event::KeyCode::Char('k') => {
                                if app.focused_panel == app::FocusedPanel::Comments {
                                    app.focused_panel = app::FocusedPanel::FileList;
                                } else if app.has_inline_commit_selector() {
                                    app.focused_panel = app::FocusedPanel::CommitSelector;
                                }
                                continue;
                            }
                            crossterm::event::KeyCode::Char('j') => {
                                if app.focused_panel == app::FocusedPanel::FileList
                                    && app.has_comment_navigator_items()
                                {
                                    app.focused_panel = app::FocusedPanel::Comments;
                                } else {
                                    app.focused_panel = app::FocusedPanel::Diff;
                                }
                                continue;
                            }
                            crossterm::event::KeyCode::Char('c') => {
                                app.enter_review_comment_mode();
                                continue;
                            }
                            // `<leader>s` toggles the commit selector pane.
                            crossterm::event::KeyCode::Char('s') => {
                                app.toggle_commit_selector();
                                continue;
                            }
                            crossterm::event::KeyCode::Char('f') => {
                                app.toggle_single_file_view();
                                continue;
                            }
                            _ => {}
                        }
                        // Otherwise fall through to normal handling
                    }

                    // Vim modal editing: route comment-box keys to the edtui
                    // overlay (app-level keys handled inside).
                    if app.input_mode == InputMode::Comment && app.comment_vim_enabled {
                        app.ensure_comment_vim_editor();
                        if handle_comment_vim_key(&mut app, key) {
                            continue;
                        }
                    }

                    // Editing the PR-tab filter is a sub-state of CommitSelect;
                    // route through the filter-specific key map so typed
                    // characters update the filter buffer rather than driving
                    // commit-list navigation.
                    let mut action =
                        if app.input_mode == InputMode::CommitSelect && app.pr_filter_editing() {
                            map_target_filter_mode(key)
                        } else {
                            map_key_to_action(key, app.input_mode, app.leader_key)
                        };

                    // Handle pending command setters (these work in any mode)
                    match action {
                        Action::PendingZCommand => {
                            pending_z = true;
                            app.pending_count = None;
                            continue;
                        }
                        Action::PendingShiftZCommand => {
                            pending_shift_z = true;
                            app.pending_count = None;
                            continue;
                        }
                        Action::PendingDCommand => {
                            pending_d = true;
                            app.pending_count = None;
                            continue;
                        }
                        Action::PendingLeaderCommand => {
                            pending_leader = true;
                            app.pending_count = None;
                            continue;
                        }
                        _ => {}
                    }

                    // Vim-style {count}{motion} (Normal mode only): digits accumulate
                    // into `pending_count`, then a following motion either scales its
                    // inner count parameter or is dispatched repeatedly. `{count}G`
                    // jumps to source line `count` (already existing behaviour).
                    if app.input_mode == InputMode::Normal {
                        match action {
                            Action::Digit(d) => {
                                let n = app.pending_count.unwrap_or(0);
                                app.pending_count = Some(
                                    (n.saturating_mul(10).saturating_add(d as usize)).min(999_999),
                                );
                                continue;
                            }
                            Action::GoToBottom if app.pending_count.is_some() => {
                                let count = app.pending_count.unwrap().max(1);
                                app.pending_count = None;
                                app.go_to_source_line(count as u32, tuicr::model::LineSide::New);
                                continue;
                            }
                            _ => {
                                if let Some(count) = app.pending_count.take() {
                                    let count = count.max(1);
                                    match &mut action {
                                        Action::CursorDown(n)
                                        | Action::CursorUp(n)
                                        | Action::ScrollLeft(n)
                                        | Action::ScrollRight(n)
                                        | Action::ScrollViewDown(n)
                                        | Action::ScrollViewUp(n) => {
                                            *n = n.saturating_mul(count);
                                        }
                                        Action::NextFile
                                        | Action::PrevFile
                                        | Action::NextHunk
                                        | Action::PrevHunk => {
                                            // Dispatch `count - 1` extra times; the
                                            // last one runs through normal dispatch
                                            // below.
                                            for _ in 1..count {
                                                dispatch_action(&mut app, action.clone());
                                            }
                                        }
                                        _ => {
                                            // Count silently discarded for non-motion
                                            // actions (mode changes, edits, etc.).
                                        }
                                    }
                                }
                            }
                        }
                    }

                    dispatch_action(&mut app, action);
                    if let Some(target) = app.take_pending_editor_target() {
                        match run_editor_from_tui(&mut terminal, &target) {
                            Ok(Ok(())) => {
                                if app.diff_source.includes_worktree_changes() {
                                    match app.reload_diff_files() {
                                        Ok((count, invalidated)) => {
                                            let invalidated_suffix = if invalidated > 0 {
                                                format!(", {invalidated} changed since last review")
                                            } else {
                                                String::new()
                                            };
                                            app.set_message(format!(
                                                "Opened {} and reloaded {count} files{invalidated_suffix}",
                                                target.path.display()
                                            ));
                                        }
                                        Err(err) => {
                                            app.set_error(format!(
                                                "Reload after editor failed: {err}"
                                            ));
                                        }
                                    }
                                } else {
                                    app.set_message(format!("Opened {}", target.path.display()));
                                }
                            }
                            Ok(Err(err)) => app.set_error(err.to_string()),
                            Err(err) => app.set_error(format!("Failed to restore terminal: {err}")),
                        }
                    }
                }
                Event::Mouse(mouse_event) => handle_mouse_event(&mut app, mouse_event),
                Event::Paste(text) => {
                    // Bracketed-paste payload — route to whichever handler is
                    // currently accepting text input. Other modes ignore.
                    // Vim comment box: feed the overlay so the buffer stays synced.
                    if app.input_mode == InputMode::Comment && app.comment_vim_enabled {
                        app.ensure_comment_vim_editor();
                        app.comment_vim_feed_paste(text);
                        continue;
                    }
                    let action = Action::Paste(text);
                    match app.input_mode {
                        InputMode::Comment => handle_comment_action(&mut app, action),
                        InputMode::Command => handle_command_action(&mut app, action),
                        InputMode::Search => handle_search_action(&mut app, action),
                        InputMode::CommitSelect if app.pr_filter_editing() => {
                            handle_commit_select_action(&mut app, action)
                        }
                        _ => {}
                    }
                }
                _ => {}
            }
        }

        if app.should_quit {
            break;
        }
    }

    terminal.restore()?;

    if let Err(e) = app.cleanup_empty_ephemeral_sessions() {
        eprintln!("Warning: failed to clean up empty review session: {e}");
    }
    if let Err(e) = app.clear_active_session_marker() {
        eprintln!("Warning: failed to clear active review session marker: {e}");
    }

    // Print pending stdout output if --stdout was used
    if let Some(output) = app.pending_stdout_output {
        print!("{output}");
    }

    Ok(())
}

fn dispatch_action(app: &mut App, action: Action) {
    match app.input_mode {
        InputMode::Help => handle_help_action(app, action),
        InputMode::Command => handle_command_action(app, action),
        InputMode::Search => handle_search_action(app, action),
        InputMode::Comment => handle_comment_action(app, action),
        InputMode::Confirm => handle_confirm_action(app, action),
        InputMode::CommitSelect => handle_commit_select_action(app, action),
        InputMode::VisualSelect => handle_visual_action(app, action),
        InputMode::SubmitResolver => handle_submit_resolver_action(app, action),
        InputMode::SubmitConfirm => handle_submit_confirm_action(app, action),
        InputMode::SubmitActionPicker => handle_submit_action_picker_action(app, action),
        InputMode::Normal => match app.focused_panel {
            FocusedPanel::FileList => handle_file_list_action(app, action),
            FocusedPanel::Comments => handle_comment_navigator_action(app, action),
            FocusedPanel::Diff => handle_diff_action(app, action),
            FocusedPanel::CommitSelector => handle_commit_selector_action(app, action),
        },
    }
}

/// Handle a comment-mode key while vim is active: app-level keys keep their
/// semantics, everything else feeds the overlay. Always returns `true`.
fn handle_comment_vim_key(app: &mut App, key: crossterm::event::KeyEvent) -> bool {
    use crossterm::event::{KeyCode, KeyModifiers};
    let ctrl = key.modifiers.contains(KeyModifiers::CONTROL);

    // An open `:` command-line captures all input until Enter/Esc.
    if app.comment_vim_command_active() {
        match key.code {
            KeyCode::Enter => app.run_comment_vim_command(),
            KeyCode::Esc => app.comment_vim_command_cancel(),
            KeyCode::Backspace => app.comment_vim_command_backspace(),
            KeyCode::Char(c) if !ctrl && !key.modifiers.contains(KeyModifiers::ALT) => {
                app.comment_vim_command_push(c)
            }
            _ => {}
        }
        return true;
    }

    // Alt+Enter (Option+Enter) accepts (save) and Alt+Esc discards (cancel)
    // directly, in any mode — no double-press. Alt is the one modified Enter/Esc
    // that reaches the app across terminals, including browser/web terminals
    // like zellij web (where Shift/Cmd+Enter get stripped or grabbed). Plain
    // Enter still inserts a newline in Insert mode, so Alt+Enter is free here.
    if key.modifiers.contains(KeyModifiers::ALT) {
        match key.code {
            KeyCode::Enter => {
                app.save_comment();
                return true;
            }
            KeyCode::Esc => {
                app.exit_comment_mode();
                return true;
            }
            _ => {}
        }
    }

    let normal = app.comment_vim_in_normal_mode();

    // In Normal mode a first plain Enter/Esc arms a confirm (header shows the
    // hint); a second consecutive press saves (`:w`) / cancels (`:q`).
    if normal && key.modifiers.is_empty() {
        match key.code {
            KeyCode::Enter => {
                app.comment_vim_enter_normal();
                return true;
            }
            // `q` behaves exactly like Esc here (arm/confirm cancel).
            KeyCode::Esc | KeyCode::Char('q') => {
                app.comment_vim_esc_normal();
                return true;
            }
            _ => {}
        }
    }
    // Any other key breaks a pending double-press sequence.
    app.comment_vim_reset_pending();

    match key.code {
        // Save shortcut in any mode (Ctrl-C cancel is handled earlier).
        KeyCode::Char('s') if ctrl => app.save_comment(),
        KeyCode::Enter if ctrl => app.save_comment(),
        // Tab cycles the comment type in Normal mode; in Insert it inserts a
        // soft tab (`comment_tab_width` spaces).
        KeyCode::Tab | KeyCode::Char('\t') if normal => app.cycle_comment_type(),
        KeyCode::Tab | KeyCode::Char('\t') => app.comment_vim_insert_soft_tab(),
        KeyCode::BackTab if normal => app.cycle_comment_type_reverse(),
        // `:` opens the command-line in Normal mode (`:w` saves, `:q` cancels).
        // Esc/Enter in Normal fall through to edtui (Esc is a no-op there).
        KeyCode::Char(':') if normal => app.start_comment_vim_command(),
        _ => app.comment_vim_feed_key(key),
    }
    true
}

fn run_editor_from_tui<W: Write>(
    terminal: &mut TerminalSession<W>,
    target: &EditorTarget,
) -> anyhow::Result<Result<(), EditorError>> {
    let suspension = terminal.suspend()?;
    let editor_result = tuicr::editor::run_editor(target);
    suspension.resume()?;
    Ok(editor_result)
}

//! Slug-addressed storage layer for review sessions.
//!
//! Layout under the platform data dir's `tuicr-fork/reviews/`:
//!
//! ```text
//! reviews/
//!   index.json                # manifest, source of truth for lookups
//!   sessions/
//!     <16-hex>.json           # one file per session, deterministic name
//! ```
//!
//! The session filename is a hash of the slug plus the canonical repo path
//! (for local) or head SHA (for PR), so the same logical session always
//! lands at the same path without consulting the manifest. The manifest is
//! the authoritative slug -> file mapping; if it goes missing or corrupts,
//! the session JSONs are self-describing and the manifest can be rebuilt by
//! walking `sessions/`.

use std::cmp::Reverse;
use std::collections::HashSet;
use std::fs;
use std::io::Write;
use std::path::{Path, PathBuf};
use std::time::{Duration, Instant, SystemTime};

use chrono::Utc;
use serde::{Deserialize, Serialize};

#[cfg(not(test))]
use directories::ProjectDirs;

use crate::error::{Result, TuicrError};
use crate::forge::traits::PrSessionKey;
use crate::hash::Fnv1aHasher;
use crate::model::ReviewSession;
use crate::model::review::SessionDiffSource;
use crate::persistence::manifest::{
    self, MANIFEST_FILENAME, ManifestEntry, ManifestKind, SESSIONS_DIRNAME,
};
use crate::slug::{self, RepoCoordinate, Slug};

const STORAGE_LOCK_FILENAME: &str = ".tuicr.lock";
const STORAGE_LOCK_TIMEOUT: Duration = Duration::from_secs(10);
#[cfg(not(test))]
const STORAGE_LOCK_STALE_AFTER: Duration = Duration::from_secs(60);
#[cfg(test)]
const STORAGE_LOCK_STALE_AFTER: Duration = Duration::from_millis(0);
const STORAGE_LOCK_REUSE_GUARD_AFTER: Duration = Duration::from_secs(12 * 60 * 60);
/// A lock file is created (`create_new`) and then has its owning PID/
/// timestamp written to it as two separate steps. A concurrent waiter that
/// reads the file in the (normally sub-millisecond) gap between those two
/// steps sees zero bytes and cannot parse an owner PID, which would
/// otherwise fall through to the "unknown owner" staleness check below and
/// -- in test builds, where [`STORAGE_LOCK_STALE_AFTER`] is `0` -- delete a
/// lock its rightful holder has not finished writing yet. Treat a
/// zero-byte lock file younger than this grace period as "not yet fully
/// written", never stale, regardless of [`STORAGE_LOCK_STALE_AFTER`].
const STORAGE_LOCK_WRITE_GRACE: Duration = Duration::from_millis(200);
const ACTIVE_SESSIONS_FILENAME: &str = "active_sessions.json";
const ACTIVE_SESSION_STALE_AFTER: Duration = Duration::from_secs(12 * 60 * 60);

// ---------- Public API ----------

/// Save a session to disk and update the manifest. The on-disk path is
/// derived from the session's slug; the slug is computed from the session's
/// fields at save time.
pub fn save_session(session: &ReviewSession) -> Result<PathBuf> {
    let reviews_dir = get_reviews_dir()?;
    save_session_in_dir(session, &reviews_dir)
}

pub(crate) fn save_session_in_dir(session: &ReviewSession, reviews_dir: &Path) -> Result<PathBuf> {
    maybe_migrate(reviews_dir)?;
    with_reviews_dir_lock(reviews_dir, || {
        save_session_in_dir_unlocked(session, reviews_dir)
    })
}

pub(crate) fn update_session_in_dir<T>(
    session_ref: &Path,
    reviews_dir: &Path,
    update: impl FnOnce(&mut ReviewSession) -> Result<T>,
) -> Result<(ReviewSession, T)> {
    maybe_migrate(reviews_dir)?;
    with_reviews_dir_lock(reviews_dir, || {
        let mut session = load_session(session_ref)?;
        let output = update(&mut session)?;
        save_session_in_dir_unlocked(&session, reviews_dir)?;
        Ok((session, output))
    })
}

pub(crate) fn save_session_by_identity<T>(
    identity: &ReviewSession,
    update: impl FnOnce(Option<ReviewSession>) -> Result<(ReviewSession, T)>,
) -> Result<(PathBuf, ReviewSession, T)> {
    let reviews_dir = get_reviews_dir()?;
    save_session_by_identity_in_dir(identity, &reviews_dir, update)
}

pub(crate) fn save_session_by_identity_in_dir<T>(
    identity: &ReviewSession,
    reviews_dir: &Path,
    update: impl FnOnce(Option<ReviewSession>) -> Result<(ReviewSession, T)>,
) -> Result<(PathBuf, ReviewSession, T)> {
    maybe_migrate(reviews_dir)?;
    with_reviews_dir_lock(reviews_dir, || {
        let path = session_path_in_dir(identity, reviews_dir)?;
        let persisted = if path.exists() {
            Some(load_session(&path)?)
        } else {
            None
        };
        let (session, output) = update(persisted)?;
        let saved_path = save_session_in_dir_unlocked(&session, reviews_dir)?;
        Ok((saved_path, session, output))
    })
}

pub(crate) fn session_path(session: &ReviewSession) -> Result<PathBuf> {
    let reviews_dir = get_reviews_dir()?;
    session_path_in_dir(session, &reviews_dir)
}

pub(crate) fn session_path_in_dir(session: &ReviewSession, reviews_dir: &Path) -> Result<PathBuf> {
    let slug = slug_for_session(session)?;
    let relative = relative_path_for_slug(&slug, session)?;
    Ok(reviews_dir.join(relative))
}

pub(crate) fn delete_session_if_empty(path: &Path) -> Result<bool> {
    let reviews_dir = get_reviews_dir()?;
    delete_session_if_empty_in_dir(path, &reviews_dir)
}

pub(crate) fn delete_session_if_empty_in_dir(path: &Path, reviews_dir: &Path) -> Result<bool> {
    maybe_migrate(reviews_dir)?;
    with_reviews_dir_lock(reviews_dir, || {
        if !path.exists() {
            return Ok(false);
        }

        let session = load_session(path)?;
        if session.has_comments() || session.has_reviewed_state() {
            return Ok(false);
        }

        remove_session_at(path, reviews_dir, &session)?;
        Ok(true)
    })
}

/// Delete a session file and its manifest entry unconditionally. Returns
/// `false` when there was no file to remove.
///
/// Unlike [`delete_session_if_empty`], this discards a session even when it
/// has reviewed-file markers. It backs the "discard reviewed-only state on
/// quit" path, where the session carries no comments worth keeping.
pub(crate) fn delete_session(path: &Path) -> Result<bool> {
    let reviews_dir = get_reviews_dir()?;
    delete_session_in_dir(path, &reviews_dir)
}

pub(crate) fn delete_session_in_dir(path: &Path, reviews_dir: &Path) -> Result<bool> {
    maybe_migrate(reviews_dir)?;
    with_reviews_dir_lock(reviews_dir, || {
        if !path.exists() {
            return Ok(false);
        }
        let session = load_session(path)?;
        remove_session_at(path, reviews_dir, &session)?;
        Ok(true)
    })
}

/// Remove `path` and prune its manifest entry. The caller must already hold
/// the reviews-dir lock and have loaded `session` from `path`.
fn remove_session_at(path: &Path, reviews_dir: &Path, session: &ReviewSession) -> Result<()> {
    let slug = slug_for_session(session)?.to_string();
    let relative = path
        .strip_prefix(reviews_dir)
        .map(Path::to_path_buf)
        .unwrap_or_else(|_| path.to_path_buf());

    let mut manifest = manifest::load_manifest(reviews_dir).unwrap_or_default();
    if let Some(bucket) = manifest.entries.get_mut(&slug) {
        bucket.retain(|entry| entry.path != relative);
        if bucket.is_empty() {
            manifest.entries.remove(&slug);
        }
        manifest::save_manifest(reviews_dir, &manifest)?;
    }

    fs::remove_file(path)?;

    Ok(())
}

pub(crate) fn mark_session_active(session: &ReviewSession, path: &Path) -> Result<()> {
    let reviews_dir = get_reviews_dir()?;
    mark_session_active_in_dir(session, path, &reviews_dir)
}

pub(crate) fn mark_session_active_in_dir(
    session: &ReviewSession,
    path: &Path,
    reviews_dir: &Path,
) -> Result<()> {
    maybe_migrate(reviews_dir)?;
    let slug = slug_for_session(session)?.to_string();
    let path = normalize_active_path(path);
    with_reviews_dir_lock(reviews_dir, || {
        let mut active = load_active_sessions_unlocked(reviews_dir).unwrap_or_default();
        active.prune_stale();
        let pid = std::process::id();
        active
            .sessions
            .retain(|entry| entry.pid != pid && entry.path != path);
        active.sessions.push(ActiveSessionEntry {
            pid,
            slug,
            path,
            last_seen_at: Utc::now(),
        });
        save_active_sessions_unlocked(reviews_dir, &active)
    })
}

pub(crate) fn clear_active_session_for_pid() -> Result<()> {
    let reviews_dir = get_reviews_dir()?;
    clear_active_session_for_pid_in_dir(&reviews_dir)
}

pub(crate) fn clear_active_session_for_pid_in_dir(reviews_dir: &Path) -> Result<()> {
    maybe_migrate(reviews_dir)?;
    with_reviews_dir_lock(reviews_dir, || {
        let mut active = load_active_sessions_unlocked(reviews_dir).unwrap_or_default();
        let pid = std::process::id();
        active.sessions.retain(|entry| entry.pid != pid);
        save_active_sessions_unlocked(reviews_dir, &active)
    })
}

pub(crate) fn active_session_paths_in_dir(reviews_dir: &Path) -> Result<HashSet<PathBuf>> {
    maybe_migrate(reviews_dir)?;
    let active = load_active_sessions_unlocked(reviews_dir).unwrap_or_default();
    Ok(active
        .sessions
        .into_iter()
        .filter(|entry| entry.is_fresh())
        .map(|entry| normalize_active_path(&entry.path))
        .collect())
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct ActiveSessionsFile {
    version: String,
    #[serde(default)]
    sessions: Vec<ActiveSessionEntry>,
}

impl Default for ActiveSessionsFile {
    fn default() -> Self {
        Self {
            version: "1.0".to_string(),
            sessions: Vec::new(),
        }
    }
}

impl ActiveSessionsFile {
    fn prune_stale(&mut self) {
        self.sessions.retain(ActiveSessionEntry::is_fresh);
    }
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct ActiveSessionEntry {
    pid: u32,
    slug: String,
    path: PathBuf,
    last_seen_at: chrono::DateTime<Utc>,
}

impl ActiveSessionEntry {
    fn is_fresh(&self) -> bool {
        let age_is_fresh = Utc::now()
            .signed_duration_since(self.last_seen_at)
            .to_std()
            .is_ok_and(|age| age <= ACTIVE_SESSION_STALE_AFTER);
        age_is_fresh && process_is_running(self.pid) && self.path.exists()
    }
}

#[cfg(unix)]
fn process_is_running(pid: u32) -> bool {
    unsafe extern "C" {
        fn kill(pid: i32, sig: i32) -> i32;
    }

    if pid == 0 {
        return false;
    }

    let result = unsafe { kill(pid as i32, 0) };
    if result == 0 {
        return true;
    }
    std::io::Error::last_os_error().kind() == std::io::ErrorKind::PermissionDenied
}

#[cfg(not(unix))]
fn process_is_running(_pid: u32) -> bool {
    true
}

fn active_sessions_path(reviews_dir: &Path) -> PathBuf {
    reviews_dir.join(ACTIVE_SESSIONS_FILENAME)
}

fn load_active_sessions_unlocked(reviews_dir: &Path) -> Result<ActiveSessionsFile> {
    let path = active_sessions_path(reviews_dir);
    match fs::read_to_string(&path) {
        Ok(contents) => serde_json::from_str(&contents)
            .map_err(|e| TuicrError::CorruptedSession(format!("active sessions parse error: {e}"))),
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => Ok(ActiveSessionsFile::default()),
        Err(e) => Err(TuicrError::Io(e)),
    }
}

fn save_active_sessions_unlocked(reviews_dir: &Path, active: &ActiveSessionsFile) -> Result<()> {
    let json = serde_json::to_string_pretty(active)?;
    write_atomic(&active_sessions_path(reviews_dir), json.as_bytes())
}

fn normalize_active_path(path: &Path) -> PathBuf {
    fs::canonicalize(path).unwrap_or_else(|_| path.to_path_buf())
}

pub(crate) fn normalize_path_for_comparison(path: &Path) -> PathBuf {
    normalize_active_path(path)
}

fn save_session_in_dir_unlocked(session: &ReviewSession, reviews_dir: &Path) -> Result<PathBuf> {
    let slug = slug_for_session(session)?;
    let relative = relative_path_for_slug(&slug, session)?;
    let full_path = reviews_dir.join(&relative);

    if let Some(parent) = full_path.parent() {
        fs::create_dir_all(parent)?;
    }
    let json = serde_json::to_string_pretty(session)?;
    write_atomic(&full_path, json.as_bytes())?;

    let mut manifest = manifest::load_manifest(reviews_dir).unwrap_or_default();
    let anchor = manifest_anchor_for(&slug);
    let entry = manifest::entry_from_session(session, relative, anchor);
    manifest.upsert(slug.to_string(), entry);
    manifest::save_manifest(reviews_dir, &manifest)?;

    Ok(full_path)
}

fn write_atomic(path: &Path, bytes: &[u8]) -> Result<()> {
    let parent = path.parent().ok_or_else(|| {
        TuicrError::Io(std::io::Error::new(
            std::io::ErrorKind::InvalidInput,
            format!("path has no parent: {}", path.display()),
        ))
    })?;
    fs::create_dir_all(parent)?;

    let file_name = path
        .file_name()
        .and_then(|name| name.to_str())
        .unwrap_or("session");
    let tmp_path = parent.join(format!(".{file_name}.{}.tmp", uuid::Uuid::new_v4()));

    {
        let mut tmp = fs::File::create(&tmp_path)?;
        tmp.write_all(bytes)?;
        tmp.sync_all().ok();
    }
    fs::rename(&tmp_path, path)?;
    Ok(())
}

struct ReviewsDirLock {
    path: PathBuf,
}

impl Drop for ReviewsDirLock {
    fn drop(&mut self) {
        let _ = fs::remove_file(&self.path);
    }
}

fn with_reviews_dir_lock<T>(reviews_dir: &Path, f: impl FnOnce() -> Result<T>) -> Result<T> {
    let _lock = acquire_reviews_dir_lock(reviews_dir)?;
    f()
}

fn acquire_reviews_dir_lock(reviews_dir: &Path) -> Result<ReviewsDirLock> {
    fs::create_dir_all(reviews_dir)?;
    let path = reviews_dir.join(STORAGE_LOCK_FILENAME);
    let started = Instant::now();
    loop {
        match fs::OpenOptions::new()
            .write(true)
            .create_new(true)
            .open(&path)
        {
            Ok(mut file) => {
                let _ = writeln!(file, "{} {}", std::process::id(), Utc::now());
                let _ = file.sync_all();
                return Ok(ReviewsDirLock { path });
            }
            Err(err) if err.kind() == std::io::ErrorKind::AlreadyExists => {
                if remove_stale_reviews_dir_lock(&path)? {
                    continue;
                }
                if started.elapsed() >= STORAGE_LOCK_TIMEOUT {
                    return Err(TuicrError::Io(std::io::Error::new(
                        std::io::ErrorKind::TimedOut,
                        format!(
                            "timed out waiting for review storage lock {}",
                            path.display()
                        ),
                    )));
                }
                std::thread::sleep(Duration::from_millis(25));
            }
            Err(err) => return Err(TuicrError::Io(err)),
        }
    }
}

fn remove_stale_reviews_dir_lock(path: &Path) -> Result<bool> {
    let metadata = match fs::metadata(path) {
        Ok(metadata) => metadata,
        Err(err) if err.kind() == std::io::ErrorKind::NotFound => return Ok(false),
        Err(err) => return Err(TuicrError::Io(err)),
    };
    let lock_age = metadata
        .modified()
        .ok()
        .and_then(|modified| SystemTime::now().duration_since(modified).ok());
    if metadata.len() == 0 && lock_age.is_none_or(|age| age < STORAGE_LOCK_WRITE_GRACE) {
        // The lock file was just created; its owner hasn't written its
        // PID/timestamp yet. Never treat this as stale -- keep waiting.
        return Ok(false);
    }
    let stale = match read_lock_owner_pid(path) {
        Some(pid) => {
            !process_is_running(pid)
                || lock_age.is_some_and(|age| age >= STORAGE_LOCK_REUSE_GUARD_AFTER)
        }
        None => lock_age.is_some_and(|age| age >= STORAGE_LOCK_STALE_AFTER),
    };
    if !stale {
        return Ok(false);
    }
    match fs::remove_file(path) {
        Ok(()) => Ok(true),
        Err(err) if err.kind() == std::io::ErrorKind::NotFound => Ok(false),
        Err(err) => Err(TuicrError::Io(err)),
    }
}

fn read_lock_owner_pid(path: &Path) -> Option<u32> {
    fs::read_to_string(path)
        .ok()?
        .split_whitespace()
        .next()?
        .parse()
        .ok()
}

/// Load a session JSON file from an absolute path.
///
/// Sessions predating `CURRENT_SESSION_VERSION` have their legacy
/// `review_comments`/`files[..].*_comments` migrated into durable threads
/// in-memory before being returned (see
/// `ReviewSession::migrate_legacy_comments_to_threads`). Migration is
/// idempotent (a session already at `CURRENT_SESSION_VERSION` is a no-op)
/// and never mutates the on-disk file — callers that want the migration
/// persisted must save the returned session explicitly.
pub fn load_session(path: &Path) -> Result<ReviewSession> {
    let contents = fs::read_to_string(path)?;
    let mut session: ReviewSession =
        serde_json::from_str(&contents).map_err(|e| TuicrError::CorruptedSession(e.to_string()))?;
    session.migrate_legacy_comments_to_threads();
    Ok(session)
}

/// Look up the persisted local session that matches the requested context.
/// Returns `None` if no matching slug is in the manifest, or if a manifest
/// entry exists but belongs to a different canonical checkout (same slug,
/// different path on disk).
pub fn load_latest_session_for_context(
    repo_path: &Path,
    branch_name: Option<&str>,
    head_commit: &str,
    diff_source: SessionDiffSource,
    commit_range: Option<&[String]>,
) -> Result<Option<(PathBuf, ReviewSession)>> {
    // PR sessions are resolved via `load_pr_session`. Mirror the old behavior
    // so callers that pass `PullRequest` here get `None` rather than an error.
    if matches!(diff_source, SessionDiffSource::PullRequest) {
        return Ok(None);
    }

    let reviews_dir = get_reviews_dir()?;
    maybe_migrate(&reviews_dir)?;

    let owner_repo = slug::resolve_owner_repo(repo_path)
        .map_err(|e| TuicrError::CorruptedSession(format!("slug derive: {e}")))?;
    let local = slug::build_local_slug(
        owner_repo,
        branch_name,
        head_commit,
        diff_source,
        commit_range,
    )
    .map_err(|e| TuicrError::CorruptedSession(format!("slug build: {e}")))?;
    let slug = Slug::Local(local);

    let manifest = manifest::load_manifest(&reviews_dir).unwrap_or_default();
    let canonical = fs::canonicalize(repo_path).unwrap_or_else(|_| repo_path.to_path_buf());
    let Some(entry) = manifest.get_local(&slug.to_string(), &canonical) else {
        return Ok(None);
    };

    let full_path = reviews_dir.join(&entry.path);
    let session = load_session(&full_path)?;
    Ok(Some((full_path, session)))
}

pub(crate) fn list_sessions_for_selector_in_dir(
    reviews_dir: &Path,
    selector: &Path,
) -> Result<Vec<(String, ManifestEntry)>> {
    maybe_migrate(reviews_dir)?;

    let manifest = manifest::load_manifest(reviews_dir).unwrap_or_default();
    let target = RepoSelector::resolve(selector);
    let mut entries: Vec<_> = manifest
        .iter()
        .filter(|(slug, entry)| target.matches(slug, entry))
        .map(|(slug, entry)| (slug.clone(), entry.clone()))
        .collect();
    entries.sort_by_key(|(_, entry)| Reverse(entry.updated_at));
    Ok(entries)
}

/// How `tuicr review list --repo <value>` interprets its argument.
///
/// A local directory is matched precisely by canonical path (so two checkouts
/// of the same repo stay separate) and contributes an `owner/repo` coordinate
/// derived from its `origin` remote. A non-directory value is parsed directly
/// as a forge coordinate (`owner/repo`, `host/owner/repo`, or a repo/PR URL).
///
/// Local sessions match by canonical path when one is known, otherwise by
/// coordinate. PR sessions have no checkout, so they always match by
/// `owner/repo` — which is what lets `--repo slatedb/slatedb` (or a slatedb
/// checkout) surface its PR sessions.
struct RepoSelector {
    canonical_path: Option<PathBuf>,
    coordinate: Option<RepoCoordinate>,
}

impl RepoSelector {
    fn resolve(selector: &Path) -> Self {
        if selector.is_dir() {
            Self {
                canonical_path: Some(
                    fs::canonicalize(selector).unwrap_or_else(|_| selector.to_path_buf()),
                ),
                coordinate: RepoCoordinate::from_repo_path(selector),
            }
        } else {
            Self {
                canonical_path: None,
                coordinate: RepoCoordinate::parse(&selector.to_string_lossy()),
            }
        }
    }

    fn matches(&self, slug: &str, entry: &ManifestEntry) -> bool {
        match entry.kind {
            // A local session is tied to a physical checkout: match it by
            // canonical path when the selector named one, else by coordinate.
            ManifestKind::Local => match &self.canonical_path {
                Some(canonical) => {
                    entry.canonical_repo_path.as_deref() == Some(canonical.as_path())
                }
                None => self.coordinate_matches(slug),
            },
            // A PR session has no checkout, so it always matches by coordinate
            // — this is what surfaces a repo's PR sessions from its checkout.
            ManifestKind::Pr { .. } => self.coordinate_matches(slug),
        }
    }

    fn coordinate_matches(&self, slug: &str) -> bool {
        let (Some(target), Ok(slug)) = (self.coordinate.as_ref(), slug.parse::<Slug>()) else {
            return false;
        };
        target.matches(&RepoCoordinate::from_slug(&slug))
    }
}

/// List every persisted session (local and PR), newest first. Backs
/// `tuicr review list --all`, which surfaces every session regardless of repo.
pub(crate) fn list_all_sessions_in_dir(reviews_dir: &Path) -> Result<Vec<(String, ManifestEntry)>> {
    maybe_migrate(reviews_dir)?;

    let manifest = manifest::load_manifest(reviews_dir).unwrap_or_default();
    let mut entries: Vec<_> = manifest
        .iter()
        .map(|(slug, entry)| (slug.clone(), entry.clone()))
        .collect();
    entries.sort_by_key(|(_, entry)| Reverse(entry.updated_at));
    Ok(entries)
}

/// Resolve a PR session's on-disk path from its slug, consulting the manifest.
/// Returns `None` when no PR entry exists for the slug. Unlike
/// [`load_pr_session`], the caller does not need to know the head SHA: the
/// manifest holds a single entry per PR slug (the current head's session).
pub(crate) fn pr_session_path_in_dir(reviews_dir: &Path, slug: &str) -> Result<Option<PathBuf>> {
    maybe_migrate(reviews_dir)?;

    let manifest = manifest::load_manifest(reviews_dir).unwrap_or_default();
    Ok(manifest
        .get_pr(slug)
        .map(|entry| reviews_dir.join(&entry.path)))
}

/// Look up the persisted PR session for a key. Returns `None` if no entry
/// exists for the slug, or if the manifest's current head differs from the
/// requested head (the old head's file may still be on disk but is not
/// surfaced).
pub fn load_pr_session(key: &PrSessionKey) -> Result<Option<(PathBuf, ReviewSession)>> {
    let reviews_dir = get_reviews_dir()?;
    maybe_migrate(&reviews_dir)?;

    let slug: Slug = key.into();
    let manifest = manifest::load_manifest(&reviews_dir).unwrap_or_default();
    let Some(entry) = manifest.get_pr(&slug.to_string()) else {
        return Ok(None);
    };

    match &entry.kind {
        ManifestKind::Pr { head_sha, .. } if head_sha == &key.head_sha => {
            let full_path = reviews_dir.join(&entry.path);
            let session = load_session(&full_path)?;
            Ok(Some((full_path, session)))
        }
        _ => Ok(None),
    }
}

/// Look up the persisted PR session for a key's *lineage* (forge kind +
/// host + owner/repo + PR number), ignoring `head_sha`, within `reviews_dir`.
fn load_pr_session_lineage_in_dir(
    reviews_dir: &Path,
    key: &PrSessionKey,
) -> Result<Option<(PathBuf, ReviewSession)>> {
    maybe_migrate(reviews_dir)?;

    let slug: Slug = key.into();
    let manifest = manifest::load_manifest(reviews_dir).unwrap_or_default();
    let Some(entry) = manifest.get_pr(&slug.to_string()) else {
        return Ok(None);
    };

    let full_path = reviews_dir.join(&entry.path);
    let session = load_session(&full_path)?;
    Ok(Some((full_path, session)))
}

/// [`ReviewStore`](crate::review_store::ReviewStore)-facing rebind: find the
/// persisted PR session for `new_key`'s *lineage* (ignoring `head_sha`),
/// update its `pr_session_key` to `new_key`, and save it under the new
/// head's canonical path — all inside a *single* `.tuicr.lock`-protected
/// critical section, the same lock every other session mutation
/// ([`update_session_in_dir`]) already shares. No new lock is introduced.
///
/// This closes a lost-update race the previous implementation had: doing
/// the lineage lookup *unlocked* and only acquiring a lock for the later
/// save meant another writer's `update_session_in_dir` (e.g. a concurrent
/// `reply_to_thread` on the same old-head file) could load-mutate-save
/// entirely in the window between the unlocked read and the locked write —
/// and that writer's update would then be silently discarded once this
/// function's now-stale in-memory copy got saved over the new head's path
/// and the manifest was repointed there. Performing the lineage lookup
/// *inside* the same lock the save uses closes that window: whichever
/// operation acquires the lock second is guaranteed to observe everything
/// the first one already committed, because `write_atomic`'s temp-file
/// rename means every reader either sees a fully-written file or the
/// previous one, never a torn write.
///
/// Residual limitation (not solved here, and not solvable without changing
/// how callers reference sessions): a caller already holding a
/// [`crate::review_store::SessionRef`]/path for the *old* head, obtained
/// *before* this rebind runs, can still validly write to that now-orphaned
/// old-head file afterwards — its own critical section is still correctly
/// serialized and durable, but the manifest/lineage lookup will no longer
/// surface it, since the old file is intentionally left in place (not
/// deleted or aliased) rather than migrated forward automatically. Callers
/// that always re-resolve a session by lineage before writing are
/// unaffected; callers holding a long-lived stale `SessionRef` across a
/// head change are not.
pub(crate) fn rebind_pr_session_to_head_in_dir(
    reviews_dir: &Path,
    new_key: &PrSessionKey,
) -> Result<Option<(PathBuf, ReviewSession)>> {
    maybe_migrate(reviews_dir)?;
    with_reviews_dir_lock(reviews_dir, || {
        let slug: Slug = new_key.into();
        let manifest = manifest::load_manifest(reviews_dir).unwrap_or_default();
        let Some(entry) = manifest.get_pr(&slug.to_string()) else {
            return Ok(None);
        };

        let full_path = reviews_dir.join(&entry.path);
        let mut session = load_session(&full_path)?;
        session.pr_session_key = Some(new_key.clone());
        let saved_path = save_session_in_dir_unlocked(&session, reviews_dir)?;
        Ok(Some((saved_path, session)))
    })
}

/// Look up the persisted PR session for a key's *lineage* (forge kind +
/// host + owner/repo + PR number), ignoring `head_sha`.
///
/// Unlike [`load_pr_session`], this surfaces the manifest's current entry
/// for the PR's slug regardless of which head SHA it was saved under. This
/// is additive: it lets a caller reuse the same durable review (its
/// threads, replies, provider mappings) across a PR head advance instead of
/// starting a new one, without changing `load_pr_session`'s existing exact
/// head-match semantics or any behavior built on it today. The returned
/// session's own `pr_session_key.head_sha` reflects the head it was last
/// saved at — callers that want to rebind it to the new head must refresh
/// anchors and re-save explicitly (see
/// [`crate::review_store::ReviewStore::refresh_thread_anchors`]).
pub fn load_pr_session_lineage(key: &PrSessionKey) -> Result<Option<(PathBuf, ReviewSession)>> {
    let reviews_dir = get_reviews_dir()?;
    load_pr_session_lineage_in_dir(&reviews_dir, key)
}

/// [`ReviewStore`](crate::review_store::ReviewStore)-facing variant of
/// [`load_pr_session_lineage`] that honors an explicit `reviews_dir`
/// (e.g. one set via `ReviewStore::with_reviews_dir`) instead of always
/// resolving the platform-global directory.
pub(crate) fn load_pr_session_lineage_for_dir(
    reviews_dir: &Path,
    key: &PrSessionKey,
) -> Result<Option<(PathBuf, ReviewSession)>> {
    load_pr_session_lineage_in_dir(reviews_dir, key)
}

/// Derive the slug for a session from its embedded fields. Local sessions
/// require resolving the repo's `origin` remote (I/O); PR sessions are
/// derived purely from the embedded `pr_session_key`.
pub fn slug_for_session(session: &ReviewSession) -> Result<Slug> {
    if let Some(key) = session.pr_session_key.as_ref() {
        return Ok(key.into());
    }
    let owner_repo = slug::resolve_owner_repo(&session.repo_path)
        .map_err(|e| TuicrError::CorruptedSession(format!("slug derive: {e}")))?;
    let local = slug::build_local_slug(
        owner_repo,
        session.branch_name.as_deref(),
        &session.base_commit,
        session.diff_source,
        session.commit_range.as_deref(),
    )
    .map_err(|e| TuicrError::CorruptedSession(format!("slug build: {e}")))?;
    Ok(Slug::Local(local))
}

